/**
 * Benchmark baseline helpers / 基准测试基线辅助工具
 *
 * Loads the aggregate baseline artifact (`docs/benchmark-baseline.json`, generated by
 * `pnpm test:bench:baseline`) and registers the stored results as static reference rows
 * inside `bench.compare()` groups, so a regression shows up directly in the comparison table.
 *
 * 读取聚合基线产物（`docs/benchmark-baseline.json`，由 `pnpm test:bench:baseline` 生成），
 * 并把已存储的结果作为静态参考行注册到 `bench.compare()` 对比组中，
 * 使性能回归可以直接在对比表中体现。
 */

import type { BaselineData, Bench, BenchRegistration, BenchRunOptions } from 'vitest'
import { existsSync, readFileSync } from 'node:fs'
import { fileURLToPath } from 'node:url'
import { expect } from 'vitest'

/** Baseline artifact location, relative to the repository root / 基线产物路径（相对仓库根目录） */
const BASELINE_PATH = fileURLToPath(
  new URL('../../../docs/benchmark-baseline.json', import.meta.url),
)

/** Minimal shape of the Vitest JSON report / Vitest JSON 报告的最小结构 */
interface BaselineReport {
  testResults?: {
    assertionResults?: {
      benchmarks?: {
        name?: string
        tasks?: (BaselineData & { name?: string; fromStore?: boolean })[]
      }[]
    }[]
  }[]
}

let cache: Map<string, BaselineData> | undefined

function loadBaseline(): Map<string, BaselineData> {
  if (cache) {
    return cache
  }

  const baseline = new Map<string, BaselineData>()
  cache = baseline
  if (!existsSync(BASELINE_PATH)) {
    return baseline
  }

  const report = JSON.parse(readFileSync(BASELINE_PATH, 'utf8')) as BaselineReport
  for (const testResult of report.testResults ?? []) {
    for (const assertion of testResult.assertionResults ?? []) {
      for (const group of assertion.benchmarks ?? []) {
        for (const task of group.tasks ?? []) {
          // Reference rows are derived, never a source of truth / 参考行是派生数据，不作为基线来源
          if (task.fromStore || !task.name || !group.name) {
            continue
          }
          baseline.set(`${group.name} > ${task.name}`, task)
        }
      }
    }
  }

  return baseline
}

/**
 * Look up the stored baseline of the benchmark registered in the current test / 读取当前测试中某个基准的基线
 * @param label - Benchmark label passed to `bench()` / 传给 `bench()` 的基准标签
 * @returns - The stored baseline data, or `undefined` when it is unavailable / 已存储的基线数据，不可用时为 `undefined`
 */
export function baselineOf(label: string): BaselineData | undefined {
  const testName = expect.getState().currentTestName
  if (!testName) {
    return undefined
  }

  return loadBaseline().get(`${testName} > ${label}`)
}

/**
 * Run benchmarks as one group, comparing them with the stored baseline / 以对比组的方式运行基准测试，并与已存储的基线对比
 *
 * Every registration gets a `<label> (baseline)` reference row when a baseline exists.
 * A single registration without a baseline falls back to `.run()`.
 *
 * 存在基线时，每个基准都会追加一行 `<label> (baseline)` 参考行；
 * 单个基准且无基线时退化为 `.run()`。
 *
 * @param bench - The `bench` fixture from the test context / 测试上下文中的 `bench` fixture
 * @param registrations - Benchmarks of this group / 该对比组的基准列表
 * @param options - Run options shared by the whole group / 整个对比组共享的运行选项
 */
export async function runBenchmarks<Name extends string>(
  bench: Bench,
  registrations: BenchRegistration<Name>[],
  options: BenchRunOptions,
): Promise<void> {
  const rows: BenchRegistration<string>[] = []
  for (const registration of registrations) {
    rows.push(registration)
    const baseline = baselineOf(registration.name)
    if (baseline) {
      rows.push(bench.from(`${registration.name} (baseline)`, () => baseline))
    }
  }

  const [single] = rows
  if (rows.length < 2) {
    await single?.run(options)
    return
  }

  await bench.compare(...rows, options)
}
